SELECT * FROM (SELECT DATE_TRUNC('MONTH', launch_date) AS launch_month, CASE WHEN cost >= 760 THEN 'high' WHEN cost >= 250 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(CASE WHEN brand = 'Stark' THEN price ELSE 0 END) AS stark_price, SORT_ARRAY(COLLECT_SET(category)) AS category_list FROM products WHERE YEAR(launch_date) >= 2024 GROUP BY DATE_TRUNC('MONTH', launch_date), CASE WHEN cost >= 760 THEN 'high' WHEN cost >= 250 THEN 'mid' ELSE 'low' END) AS sub WHERE stark_price < 60
